class Solution {

    public void quick_sort(int[] nums, int l, int r){
        if(l >= r) return;
        int x = nums[l+r >> 1];
        int i = l-1;
        int j = r+1;
        while(i < j){
            do i++; while(nums[i] < x);
            do j--; while(nums[j] > x);
            if(i < j) {
                int tmp = nums[i];
                nums[i] = nums[j];
                nums[j] = tmp;
            }
        }
        quick_sort(nums,l,j);
        quick_sort(nums,j+1,r);
    }

    public int[] sortArray(int[] nums) {
        int n = nums.length;
        quick_sort(nums,0,n-1);
        return nums;
    }
}
